#!/usr/bin/env python3
"""i3-style: apply a theme to your i3 config file."""

import os
import re
import sys
import subprocess
import time

from themes import THEMES
from css_colors import nearest_color_name


# ---------- Argument parsing (matching clap-like behavior) ----------

USAGE = """USAGE:
    executable [FLAGS] [OPTIONS] [theme]
"""

HELP = """i3-style 1.0
Make your i3 config a bit more stylish

USAGE:
    executable [FLAGS] [OPTIONS] [theme]

FLAGS:
    -h, --help        Prints help information
    -l, --list-all    Print a list of all available themes
    -r, --reload      Apply the theme by reloading the config
    -s, --save        Set the output file to the path of the input file
    -V, --version     Prints version information

OPTIONS:
    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.
    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>
    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others
                             [default: ]

ARGS:
    <theme>    The theme to use
"""

VERSION = "i3-style 1.0"


class Args:
    def __init__(self):
        self.theme = None
        self.config = None
        self.output = None
        self.to_theme = None       # None = not given; "" = given but empty
        self.reload = False
        self.save = False
        self.list_all = False


def parse_args(argv):
    a = Args()
    i = 0

    def take_value(flag, idx):
        if idx + 1 >= len(argv):
            sys.stderr.write("error: a value is required for '%s' but none was supplied\n\n" % flag)
            sys.stderr.write(USAGE)
            sys.exit(1)
        return argv[idx + 1]

    while i < len(argv):
        arg = argv[i]
        if arg == "-h" or arg == "--help":
            sys.stdout.write(HELP)
            sys.exit(0)
        elif arg == "-V" or arg == "--version":
            sys.stdout.write(VERSION + "\n")
            sys.exit(0)
        elif arg == "-l" or arg == "--list-all":
            a.list_all = True
        elif arg == "-r" or arg == "--reload":
            a.reload = True
        elif arg == "-s" or arg == "--save":
            a.save = True
        elif arg == "-c" or arg == "--config":
            a.config = take_value(arg, i)
            i += 1
        elif arg.startswith("--config="):
            a.config = arg[len("--config="):]
        elif arg == "-o" or arg == "--output":
            a.output = take_value(arg, i)
            i += 1
        elif arg.startswith("--output="):
            a.output = arg[len("--output="):]
        elif arg == "-t" or arg == "--to-theme":
            # Default value is "" if flag given with no value; if value comes next, take it
            if i + 1 < len(argv) and not argv[i + 1].startswith("-"):
                a.to_theme = argv[i + 1]
                i += 1
            else:
                a.to_theme = ""
        elif arg.startswith("--to-theme="):
            a.to_theme = arg[len("--to-theme="):]
        elif arg.startswith("-"):
            sys.stderr.write("error: Found argument '%s' which wasn't expected\n\n" % arg)
            sys.stderr.write(USAGE)
            sys.exit(1)
        else:
            if a.theme is None:
                a.theme = arg
            else:
                sys.stderr.write("error: The value '%s' was provided, but multiple values for <theme> were not expected\n\n" % arg)
                sys.stderr.write(USAGE)
                sys.exit(1)
        i += 1
    return a


# ---------- YAML parsing (minimal, for our theme format) ----------

def parse_yaml(text):
    """Minimal YAML parser for the i3-style theme format.
    Handles simple nested maps and string values (with or without quotes).
    """
    lines = text.splitlines()
    # Remove YAML document start markers and empty/comment lines
    cleaned = []
    for raw in lines:
        # strip trailing comment starting with ' #' (but not in quotes)
        line = raw
        # remove trailing whitespace
        if line.strip() == '---':
            continue
        cleaned.append(line)

    pos = [0]

    def indent_of(line):
        n = 0
        for c in line:
            if c == ' ':
                n += 1
            else:
                break
        return n

    def parse_scalar(s):
        s = s.strip()
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]
        if s.startswith("'") and s.endswith("'"):
            return s[1:-1]
        return s

    def parse_block(base_indent):
        result = {}
        while pos[0] < len(cleaned):
            line = cleaned[pos[0]]
            if line.strip() == '' or line.lstrip().startswith('#'):
                pos[0] += 1
                continue
            ind = indent_of(line)
            if ind < base_indent:
                return result
            if ind > base_indent:
                # shouldn't happen at top of block
                return result
            # parse "key: value"
            stripped = line[ind:]
            # detect "key: {}" (empty map)
            m = re.match(r'^([^:]+):\s*(.*)$', stripped)
            if not m:
                pos[0] += 1
                continue
            key = m.group(1).strip()
            rest = m.group(2)
            pos[0] += 1
            if rest.strip() == '' or rest.strip() == '{}':
                # nested map (possibly empty)
                if rest.strip() == '{}':
                    result[key] = {}
                else:
                    # Peek next non-empty line to determine nested indent
                    # Skip empty lines
                    save = pos[0]
                    while pos[0] < len(cleaned) and (cleaned[pos[0]].strip() == '' or cleaned[pos[0]].lstrip().startswith('#')):
                        pos[0] += 1
                    if pos[0] >= len(cleaned):
                        result[key] = {}
                        continue
                    next_indent = indent_of(cleaned[pos[0]])
                    if next_indent <= base_indent:
                        result[key] = {}
                    else:
                        result[key] = parse_block(next_indent)
            else:
                result[key] = parse_scalar(rest)
        return result

    return parse_block(0)


def load_theme_from_file(path):
    with open(path, 'r') as f:
        data = parse_yaml(f.read())

    # Convert to the internal theme format: 
    #   {"window_colors": {...}, "bar_colors": {...}}
    # resolving color references via top-level "colors" map
    color_palette = data.get('colors', {}) or {}

    def resolve(v):
        if isinstance(v, str):
            if v.startswith('#'):
                return v
            # named reference
            if v in color_palette:
                return color_palette[v]
            return v  # return literal (may be invalid)
        return v

    def resolve_block(block):
        result = {}
        for k, v in block.items():
            if isinstance(v, dict):
                result[k] = {kk: resolve(vv) for kk, vv in v.items()}
            else:
                result[k] = resolve(v)
        return result

    wc = data.get('window_colors') or {}
    bc = data.get('bar_colors') or {}
    if not isinstance(wc, dict):
        wc = {}
    if not isinstance(bc, dict):
        bc = {}
    return {
        'window_colors': resolve_block(wc),
        'bar_colors': resolve_block(bc),
    }


# ---------- Theme application ----------

BAR_COLOR_KEYS_ORDER = [
    'separator', 'background', 'statusline',
    'focused_workspace', 'active_workspace', 'inactive_workspace', 'urgent_workspace',
]

BAR_WORKSPACE_KEYS = {'focused_workspace', 'active_workspace', 'inactive_workspace', 'urgent_workspace'}
BAR_SIMPLE_KEYS = {'separator', 'background', 'statusline'}
BAR_ALL_KEYS = BAR_WORKSPACE_KEYS | BAR_SIMPLE_KEYS

CLIENT_KEYS_ORDER = [
    'focused', 'focused_inactive', 'unfocused', 'urgent',
]


def build_bar_workspace_line(keyword, theme_entry, original_third=None):
    """Build a bar workspace line from theme data.
    If original_third is provided, appends it (or theme indicator) as 4th color.
    Returns just the color portion after the keyword (without the leading indent).
    """
    if theme_entry is None:
        return None
    border = theme_entry.get('border', '')
    bg = theme_entry.get('background', '')
    text = theme_entry.get('text', '')
    indicator = theme_entry.get('indicator', None)
    parts = [keyword, border, bg, text]
    if original_third is not None:
        if indicator is not None:
            parts.append(indicator)
        else:
            parts.append(original_third)
    return ' '.join(parts)


def build_bar_simple_line(keyword, value):
    return '%s %s' % (keyword, value)


def build_client_line(keyword, theme_entry):
    border = theme_entry.get('border', '')
    bg = theme_entry.get('background', '')
    text = theme_entry.get('text', '')
    indicator = theme_entry.get('indicator', '')
    return '%s %s %s %s %s' % (keyword, border, bg, text, indicator)


CLIENT_RE = re.compile(r'^(\s*)(client\.(?:focused|focused_inactive|unfocused|urgent))\b(.*)$')
BAR_START_RE = re.compile(r'^(\s*)bar\s*\{(.*)$')
COLORS_START_RE = re.compile(r'^(\s*)colors\s*\{(.*)$')
# match any bar colors directive line 
BAR_LINE_RE = re.compile(r'^(\s*)(focused_workspace|active_workspace|inactive_workspace|urgent_workspace|separator|background|statusline)\b(.*)$')
TOKEN_SPLIT_RE = re.compile(r'\s+')


def count_color_tokens(rest):
    """Count color tokens (either starting with # or $) on the rest of a line."""
    tokens = [t for t in rest.strip().split() if t]
    # Only count tokens that look like color values (start with # or $)
    count = 0
    for t in tokens:
        if t.startswith('#') or t.startswith('$'):
            count += 1
        else:
            break
    return count, tokens


def extract_color_tokens(rest):
    """Extract consecutive color tokens (starting with # or $) from beginning of rest."""
    tokens = [t for t in rest.strip().split() if t]
    cols = []
    for t in tokens:
        if t.startswith('#') or t.startswith('$'):
            cols.append(t)
        else:
            break
    return cols


def apply_theme(config_text, theme):
    """Apply the theme to the config_text and return the new text."""
    lines = config_text.split('\n')
    # Detect trailing newline
    had_trailing_newline = config_text.endswith('\n')
    if had_trailing_newline:
        lines = lines[:-1]

    window_colors = theme.get('window_colors') or {}
    bar_colors = theme.get('bar_colors') or {}

    # --- Pass 1: Identify bar blocks and colors sub-blocks ---
    # We'll do a single forward pass, building output line by line.

    # Which client.* states are defined in the theme
    # Track seen client states to know which ones to append
    out_lines = []
    i = 0
    n = len(lines)
    seen_clients = set()

    # We need to track bar block nesting. Approach: state machine.
    # States: 'top', 'in_bar', 'in_colors'
    state = 'top'
    bar_close_indent = ''  # track for inserting colors block
    colors_close_indent = ''  # track for inserting entries
    # When we are in colors block, we collect entries we've seen.
    seen_bar = set()
    # Save lines for bar block that hasn't yet closed
    # We use a stack-like approach: when we enter bar, we store index where we'd insert colors block at end of bar
    # But since we're streaming, we'll handle braces by scanning.

    # Simpler approach: preprocess to find all bar blocks (start line, open brace pos, end line of bar, positions)

    # Identify bar blocks as (start_line, end_line). A bar block starts with `bar {` on a line
    # and ends with matching `}`. Inside, we look for `colors {` and its matching `}`.

    # We need to identify matching braces. This is a simple brace counter.

    # Find bar blocks
    bar_blocks = []  # list of dicts with start_idx, end_idx, end_indent, colors_start_idx, colors_end_idx, colors_end_indent
    i = 0
    while i < n:
        line = lines[i]
        m = BAR_START_RE.match(line)
        if m:
            # found bar {
            depth = 0
            # Count braces on this line
            rest = m.group(2)
            depth = 1 + rest.count('{') - rest.count('}')
            # But if '{' was from bar itself, count that too. We already counted bar's '{' as 1.
            # For rest: count additional '{' and '}'.
            # If depth becomes 0 on same line, the bar block is empty
            bar_start = i
            j = i
            while depth > 0 and j < n:
                j += 1
                if j >= n:
                    break
                depth += lines[j].count('{') - lines[j].count('}')
            # bar_end = j
            bar_end = j if j < n else n - 1
            # Find leading whitespace of closing } on bar_end line
            end_line = lines[bar_end] if bar_end < n else ''
            # Get indent of the } at bar_end. In typical case the } is at start of bar_end line.
            # Compute leading whitespace
            end_indent = re.match(r'^(\s*)', end_line).group(1)

            # Within bar block, find `colors {`
            colors_start = None
            colors_end = None
            colors_end_indent = None
            k = bar_start + 1
            while k < bar_end:
                cm = COLORS_START_RE.match(lines[k])
                if cm:
                    # found colors {
                    colors_start = k
                    rest2 = cm.group(2)
                    d2 = 1 + rest2.count('{') - rest2.count('}')
                    kk = k
                    while d2 > 0 and kk < bar_end:
                        kk += 1
                        if kk >= n:
                            break
                        d2 += lines[kk].count('{') - lines[kk].count('}')
                    colors_end = kk
                    colors_end_line = lines[colors_end] if colors_end < n else ''
                    colors_end_indent = re.match(r'^(\s*)', colors_end_line).group(1)
                    break
                k += 1

            bar_blocks.append({
                'start': bar_start,
                'end': bar_end,
                'end_indent': end_indent,
                'colors_start': colors_start,
                'colors_end': colors_end,
                'colors_end_indent': colors_end_indent,
            })
            i = bar_end + 1
        else:
            i += 1

    # Build mapping from line index to bar block info
    bar_by_start = {b['start']: b for b in bar_blocks}
    colors_by_start = {}
    colors_by_end = {}
    bar_by_end = {}
    for b in bar_blocks:
        if b['colors_start'] is not None:
            colors_by_start[b['colors_start']] = b
            colors_by_end[b['colors_end']] = b
        bar_by_end[b['end']] = b

    # --- Pass 2: Build output ---

    # State tracking
    in_bar = None  # bar block dict or None
    in_colors = None  # colors block's bar dict or None
    colors_seen = set()  # which bar color keys were seen/replaced in the current colors block

    i = 0
    while i < n:
        line = lines[i]

        # Check if starting a bar block
        if i in bar_by_start and in_bar is None:
            in_bar = bar_by_start[i]
            out_lines.append(line)
            i += 1
            continue

        # Check if ending the current bar block (closing })
        if in_bar is not None and i == in_bar['end']:
            # Before outputting the closing }, check if colors block is missing
            if in_bar['colors_start'] is None:
                # Insert a new colors block if there are bar colors to insert
                # Only insert if theme has any bar colors
                if bar_colors:
                    # Check if there's anything to insert
                    any_def = any(k in bar_colors for k in BAR_ALL_KEYS)
                    if any_def:
                        # Insert `  colors {`
                        insert_indent = '  '
                        content_indent = '    '
                        out_lines.append(insert_indent + 'colors {')
                        # For each bar color key, write it if defined in theme, else skip
                        for key in BAR_COLOR_KEYS_ORDER:
                            if key not in bar_colors:
                                continue
                            v = bar_colors[key]
                            if key in BAR_SIMPLE_KEYS:
                                out_lines.append(content_indent + build_bar_simple_line(key, v))
                            else:
                                # workspace - missing input so no original_third, no trailing 4th
                                border = v.get('border', '')
                                bg = v.get('background', '')
                                text = v.get('text', '')
                                out_lines.append(content_indent + '%s %s %s %s ' % (key, border, bg, text))
                        out_lines.append(insert_indent + '}')
            out_lines.append(line)
            in_bar = None
            i += 1
            continue

        # Check if starting a colors block
        if in_bar is not None and i in colors_by_start and in_colors is None:
            in_colors = colors_by_start[i]
            colors_seen = set()
            out_lines.append(line)
            i += 1
            continue

        # Check if ending the current colors block
        if in_colors is not None and i == in_colors['colors_end']:
            # Append missing keys at the end
            add_indent = in_colors['colors_end_indent'] + in_colors['colors_end_indent']
            for key in BAR_COLOR_KEYS_ORDER:
                if key in colors_seen:
                    continue
                if key not in bar_colors:
                    continue
                v = bar_colors[key]
                if key in BAR_SIMPLE_KEYS:
                    out_lines.append(add_indent + build_bar_simple_line(key, v))
                else:
                    border = v.get('border', '')
                    bg = v.get('background', '')
                    text = v.get('text', '')
                    out_lines.append(add_indent + '%s %s %s %s ' % (key, border, bg, text))
            out_lines.append(line)
            in_colors = None
            i += 1
            continue

        # If inside colors block, filter and process lines
        if in_colors is not None:
            stripped = line.lstrip()
            # Comments and blank lines pass through
            if stripped == '' or stripped.startswith('#'):
                out_lines.append(line)
                i += 1
                continue
            m = BAR_LINE_RE.match(line)
            if m:
                indent = m.group(1)
                key = m.group(2)
                rest = m.group(3)
                colors_seen.add(key)
                if key in BAR_SIMPLE_KEYS:
                    if key in bar_colors:
                        out_lines.append(indent + build_bar_simple_line(key, bar_colors[key]))
                    else:
                        out_lines.append(line)  # unchanged
                else:
                    # workspace
                    if key in bar_colors:
                        v = bar_colors[key]
                        border = v.get('border', '')
                        bg = v.get('background', '')
                        text = v.get('text', '')
                        indicator = v.get('indicator', None)
                        orig_cols = extract_color_tokens(rest)
                        num = len(orig_cols)
                        if num >= 3:
                            fourth = indicator if indicator is not None else orig_cols[2]
                            out_lines.append(indent + '%s %s %s %s %s' % (key, border, bg, text, fourth))
                        else:
                            out_lines.append(indent + '%s %s %s %s' % (key, border, bg, text))
                    else:
                        out_lines.append(line)
                i += 1
                continue
            # Unknown directive inside colors block: drop it
            i += 1
            continue

        # Outside colors block: client lines
        cm = CLIENT_RE.match(line)
        if cm:
            indent = cm.group(1)
            key = cm.group(2)  # e.g., client.focused
            sub = key.split('.', 1)[1]  # focused
            seen_clients.add(sub)
            if sub in window_colors:
                out_lines.append(indent + build_client_line(key, window_colors[sub]))
            else:
                out_lines.append(line)  # unchanged
            i += 1
            continue

        # Otherwise pass through
        out_lines.append(line)
        i += 1

    # --- Append missing client lines at end ---
    for sub in CLIENT_KEYS_ORDER:
        if sub in seen_clients:
            continue
        if sub in window_colors:
            out_lines.append(build_client_line('client.' + sub, window_colors[sub]))

    result = '\n'.join(out_lines)
    if had_trailing_newline:
        result += '\n'
    return result


# ---------- --to-theme generation ----------

def extract_hex(token):
    """If token is a hex color like #xxx or #xxxxxx, return uppercased #XXXXXX. Else None."""
    if not isinstance(token, str):
        return None
    if not token.startswith('#'):
        return None
    rest = token[1:]
    if len(rest) == 3 and all(c in '0123456789abcdefABCDEF' for c in rest):
        # Expand to 6 chars by duplication? Actually the tool keeps the original 3-char representation.
        # But when listing in the colors map, it uses the original hex. Since hex_key needs to be unique,
        # use the uppercased form.
        return '#' + rest.upper()
    if len(rest) == 6 and all(c in '0123456789abcdefABCDEF' for c in rest):
        return '#' + rest.upper()
    return None


def is_hex_token(token):
    return extract_hex(token) is not None


def to_theme(config_text):
    """Generate a YAML theme from the given config."""
    lines = config_text.split('\n')
    n = len(lines)

    # Find bar blocks and within them, colors blocks
    bar_blocks = []
    i = 0
    while i < n:
        line = lines[i]
        m = BAR_START_RE.match(line)
        if m:
            depth = 1 + m.group(2).count('{') - m.group(2).count('}')
            bar_start = i
            j = i
            while depth > 0 and j < n - 1:
                j += 1
                depth += lines[j].count('{') - lines[j].count('}')
            bar_end = j
            # find colors {
            colors_start = None
            colors_end = None
            k = bar_start + 1
            while k < bar_end:
                cm = COLORS_START_RE.match(lines[k])
                if cm:
                    colors_start = k
                    d2 = 1 + cm.group(2).count('{') - cm.group(2).count('}')
                    kk = k
                    while d2 > 0 and kk < bar_end:
                        kk += 1
                        d2 += lines[kk].count('{') - lines[kk].count('}')
                    colors_end = kk
                    break
                k += 1
            bar_blocks.append({
                'start': bar_start,
                'end': bar_end,
                'colors_start': colors_start,
                'colors_end': colors_end,
            })
            i = bar_end + 1
        else:
            i += 1

    # Collect colors in order of first appearance
    color_order = []          # list of hex keys (uppercased, e.g. "#FF0000")
    color_to_name = {}        # hex_upper -> color name (e.g., "red", "red-1")
    name_counts = {}          # css_name -> count (for suffixes)
    hex_to_original = {}      # hex_upper -> first seen original hex string (preserving case)

    def register(hex_token):
        """Register a hex token. Returns the color name assigned."""
        h = extract_hex(hex_token)
        if h is None:
            return None
        if h in color_to_name:
            return color_to_name[h]
        css_name = nearest_color_name(h)
        if css_name in name_counts:
            idx = name_counts[css_name]
            name_counts[css_name] = idx + 1
            assigned = '%s-%d' % (css_name, idx)
        else:
            name_counts[css_name] = 1
            assigned = css_name
        color_to_name[h] = assigned
        color_order.append(h)
        # Store original representation (preserve case)
        # Keep original with leading '#'; ensure uppercase form for consistency  
        hex_to_original[h] = hex_token if hex_token.startswith('#') else '#' + hex_token
        return assigned

    # Parse window_colors from client.* lines
    window_colors = {}  # name -> {border, background, text, indicator}
    for line in lines:
        cm = CLIENT_RE.match(line)
        if cm:
            key = cm.group(2).split('.', 1)[1]
            rest = cm.group(3).strip()
            tokens = [t for t in rest.split() if t]
            # Take up to 4 hex tokens
            hex_tokens = []
            for t in tokens:
                if is_hex_token(t):
                    hex_tokens.append(t)
                    if len(hex_tokens) == 4:
                        break
                else:
                    break
            if len(hex_tokens) == 4:
                entry = {}
                for idx_kind, kind in enumerate(['border', 'background', 'text', 'indicator']):
                    nm = register(hex_tokens[idx_kind])
                    if nm is not None:
                        entry[kind] = nm
                # Only keep the LAST assignment per key (or first? Let's keep first seen line)
                if key not in window_colors:
                    window_colors[key] = entry

    # Parse bar_colors from bar blocks
    bar_colors = {}  # {'background': name, 'statusline': name, 'separator': name,
                     #  'focused_workspace': {border,bg,text}, 'urgent_workspace': {...},
                     #  'active_workspace': {...}, 'inactive_workspace': {...}}
    for bb in bar_blocks:
        if bb['colors_start'] is None:
            continue
        for idx in range(bb['colors_start'] + 1, bb['colors_end']):
            line = lines[idx]
            bm = BAR_LINE_RE.match(line)
            if not bm:
                continue
            key = bm.group(2)
            rest = bm.group(3).strip()
            tokens = [t for t in rest.split() if t]
            hex_tokens = []
            for t in tokens:
                if is_hex_token(t):
                    hex_tokens.append(t)
                else:
                    break
            if key in BAR_SIMPLE_KEYS:
                if len(hex_tokens) >= 1:
                    nm = register(hex_tokens[0])
                    if key not in bar_colors and nm is not None:
                        bar_colors[key] = nm
            else:
                # workspace - only track border/background/text (3 colors)
                if len(hex_tokens) >= 3:
                    entry = {}
                    for idx_kind, kind in enumerate(['border', 'background', 'text']):
                        nm = register(hex_tokens[idx_kind])
                        if nm is not None:
                            entry[kind] = nm
                    if key not in bar_colors:
                        bar_colors[key] = entry

    # --- Generate YAML output ---
    out = []
    out.append('---')
    out.append('meta:')
    out.append('  description: AUTOMATICALLY GENERATED THEME')
    if color_order:
        out.append('colors:')
        for h in color_order:
            nm = color_to_name[h]
            orig = hex_to_original[h]
            out.append('  %s: "%s"' % (nm, orig))
    else:
        out.append('colors: {}')

    # window_colors
    if window_colors:
        out.append('window_colors:')
        for wk in ['focused', 'focused_inactive', 'unfocused', 'urgent']:
            if wk in window_colors:
                out.append('  %s:' % wk)
                ent = window_colors[wk]
                for ck in ['border', 'background', 'text', 'indicator']:
                    if ck in ent:
                        out.append('    %s: %s' % (ck, ent[ck]))
    else:
        out.append('window_colors: {}')

    # bar_colors
    has_bar = bool(bar_colors)
    if has_bar:
        out.append('bar_colors:')
        # Order: background, statusline, separator, focused_workspace, urgent_workspace
        for sk in ['background', 'statusline', 'separator']:
            if sk in bar_colors:
                out.append('  %s: %s' % (sk, bar_colors[sk]))
        for wk in ['focused_workspace', 'urgent_workspace']:
            if wk in bar_colors:
                out.append('  %s:' % wk)
                ent = bar_colors[wk]
                for ck in ['border', 'background', 'text']:
                    if ck in ent:
                        out.append('    %s: %s' % (ck, ent[ck]))
    else:
        out.append('bar_colors: {}')
    out.append('')
    return '\n'.join(out)


# ---------- Theme lookup ----------

def find_theme(name):
    """Find a theme by name. Returns the theme dict or None."""
    for t_name, _desc, t in THEMES:
        if t_name == name:
            return t
    return None


def load_theme(arg):
    """Load a theme. If arg looks like a path (has separator or exists), load from file.
    Otherwise look up in built-in themes."""
    # If arg is a path-like (contains '/' or '.yaml' or exists as file), load from file
    if '/' in arg or os.path.exists(arg) or arg.endswith('.yaml') or arg.endswith('.yml'):
        try:
            return load_theme_from_file(arg)
        except FileNotFoundError as e:
            sys.stderr.write('Could not open theme: %s - No such file or directory (os error 2)\n Use `i3-style --list-all` to see the available themes.\n' % arg)
            sys.exit(1)
    t = find_theme(arg)
    if t is not None:
        return t
    # Try as file
    try:
        return load_theme_from_file(arg)
    except FileNotFoundError:
        sys.stderr.write('Could not open theme: %s - No such file or directory (os error 2)\n Use `i3-style --list-all` to see the available themes.\n' % arg)
        sys.exit(1)


# ---------- Config location & helpers ----------

def find_default_config():
    home = os.environ.get('HOME', '')
    candidates = [
        os.path.join(home, '.config', 'i3', 'config'),
        os.path.join(home, '.i3', 'config'),
    ]
    for c in candidates:
        if os.path.isfile(c):
            return c
    return None


def list_all_themes():
    sys.stdout.write('\nAvailable themes:\n\n')
    for name, desc, _ in THEMES:
        sys.stdout.write('  %-18s - %s\n' % (name, desc))


def save_backup(config_path):
    """Save a backup of the config file to /tmp/i3-style/<timestamp>/config-input."""
    ts = str(int(time.time()))
    tmpdir = os.path.join('/tmp', 'i3-style', ts)
    try:
        os.makedirs(tmpdir, exist_ok=True)
    except Exception:
        return
    backup_path = os.path.join(tmpdir, 'config-input')
    try:
        with open(config_path, 'rb') as f:
            content = f.read()
        with open(backup_path, 'wb') as f:
            f.write(content)
    except Exception:
        return
    sys.stderr.write('saving config at %s to %s\n' % (config_path, backup_path))


def validate_config(config_path):
    """Run i3 -C -c <path> to validate. Returns True/False and prints error messages."""
    try:
        result = subprocess.run(['i3', '-C', '-c', config_path], capture_output=True)
        if result.returncode != 0:
            sys.stderr.write('Could not validate config.\n')
            sys.stderr.write('Use `i3 -C -c %s` to see validation errors.\n' % config_path)
            return False
        return True
    except FileNotFoundError as e:
        sys.stderr.write('Could not validate config with `i3 -C -c %s` (is i3 in the PATH?) No such file or directory (os error 2)\n' % config_path)
        return False
    except Exception as e:
        sys.stderr.write('Could not validate config with `i3 -C -c %s`: %s\n' % (config_path, e))
        return False


def reload_i3():
    try:
        subprocess.run(['i3-msg', 'reload'], capture_output=True, check=True)
    except FileNotFoundError:
        sys.stderr.write('Could not reload config with i3-msg: No such file or directory (os error 2)\n')
    except subprocess.CalledProcessError as e:
        sys.stderr.write('Could not reload config with i3-msg: command failed\n')


# ---------- Main ----------

def main(argv):
    a = parse_args(argv[1:])

    if a.list_all:
        list_all_themes()
        return 0

    # Handle --to-theme mode
    if a.to_theme is not None:
        # Use the value if provided, else default to default i3 config
        path = a.to_theme if a.to_theme != '' else (a.config or find_default_config())
        if not path:
            sys.stderr.write('Could not find i3 config\n')
            return 1
        save_backup(path)
        if not validate_config(path):
            return 1
        try:
            with open(path, 'r') as f:
                content = f.read()
        except Exception as e:
            sys.stderr.write('Could not read config: %s\n' % e)
            return 1
        out = to_theme(content)
        sys.stdout.write(out)
        return 0

    # Normal mode: apply theme
    if a.theme is None:
        sys.stdout.write('USAGE:\n    executable [FLAGS] [OPTIONS] [theme]\n\n')
        sys.stdout.write('Select a theme as the first argument. Use `--list-all` to see the themes.\n')
        return 0

    # Determine input file
    config_path = a.config if a.config else find_default_config()
    if config_path is None:
        sys.stderr.write('Could not find i3 config\n')
        return 1

    # Backup the input config
    save_backup(config_path)

    # Validate the input config with i3 -C
    if not validate_config(config_path):
        return 1

    # Load the theme
    theme = load_theme(a.theme)

    # Read config and apply theme
    try:
        with open(config_path, 'r') as f:
            config_text = f.read()
    except Exception as e:
        sys.stderr.write('Could not read config: %s\n' % e)
        return 1

    new_text = apply_theme(config_text, theme)

    # Determine output
    out_path = a.output
    if out_path is None and a.save:
        out_path = config_path

    if out_path is None:
        sys.stdout.write(new_text)
    else:
        # Write to output. The docs say clap's writer opens the file.
        try:
            with open(out_path, 'w') as f:
                f.write(new_text)
        except Exception as e:
            sys.stderr.write('Could not write output: %s\n' % e)
            return 1

    if a.reload:
        reload_i3()

    return 0


if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        sys.exit(0)
