def parse_yaml(text):
    """Minimal YAML parser for the i3-style theme format.
    Handles simple nested maps and string values (with or without quotes).
    """
    lines = text.splitlines()
    # Remove YAML document start markers and empty/comment lines
    cleaned = []
    for raw in lines:
        # strip trailing comment starting with ' #' (but not in quotes)
        line = raw
        # remove trailing whitespace
        if line.strip() == '---':
            continue
        cleaned.append(line)

    pos = [0]

    def indent_of(line):
        n = 0
        for c in line:
            if c == ' ':
