    def parse_scalar(s):
        s = s.strip()
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]
        if s.startswith("'") and s.endswith("'"):
            return s[1:-1]
        return s

    def parse_block(base_indent):
        result = {}
        while pos[0] < len(cleaned):
            line = cleaned[pos[0]]
            if line.strip() == '' or line.lstrip().startswith('#'):
                pos[0] += 1
                continue
            ind = indent_of(line)
            if ind < base_indent:
                return result
            if ind > base_indent:
                # shouldn't happen at top of block
                return result
            # parse "key: value"
            stripped = line[ind:]
