                    # Skip empty lines
                    save = pos[0]
                    while pos[0] < len(cleaned) and (cleaned[pos[0]].strip() == '' or cleaned[pos[0]].lstrip().startswith('#')):
                        pos[0] += 1
                    if pos[0] >= len(cleaned):
                        result[key] = {}
                        continue
                    next_indent = indent_of(cleaned[pos[0]])
                    if next_indent <= base_indent:
                        result[key] = {}
                    else:
                        result[key] = parse_block(next_indent)
            else:
                result[key] = parse_scalar(rest)
        return result

    return parse_block(0)


def load_theme_from_file(path):
    with open(path, 'r') as f:
        data = parse_yaml(f.read())

    # Convert to the internal theme format: 
    #   {"window_colors": {...}, "bar_colors": {...}}
    # resolving color references via top-level "colors" map
    color_palette = data.get('colors', {}) or {}

    def resolve(v):
        if isinstance(v, str):
            if v.startswith('#'):
                return v
            # named reference
            if v in color_palette:
                return color_palette[v]
            return v  # return literal (may be invalid)
        return v

    def resolve_block(block):
        result = {}
        for k, v in block.items():
            if isinstance(v, dict):
                result[k] = {kk: resolve(vv) for kk, vv in v.items()}
            else:
                result[k] = resolve(v)
        return result

    wc = data.get('window_colors') or {}
    bc = data.get('bar_colors') or {}
    if not isinstance(wc, dict):
        wc = {}
    if not isinstance(bc, dict):
        bc = {}
    return {
        'window_colors': resolve_block(wc),
        'bar_colors': resolve_block(bc),
    }


