]

BAR_WORKSPACE_KEYS = {'focused_workspace', 'active_workspace', 'inactive_workspace', 'urgent_workspace'}
BAR_SIMPLE_KEYS = {'separator', 'background', 'statusline'}
BAR_ALL_KEYS = BAR_WORKSPACE_KEYS | BAR_SIMPLE_KEYS

CLIENT_KEYS_ORDER = [
