]


def build_bar_workspace_line(keyword, theme_entry, original_third=None):
    """Build a bar workspace line from theme data.
    If original_third is provided, appends it (or theme indicator) as 4th color.
    Returns just the color portion after the keyword (without the leading indent).
    """
    if theme_entry is None:
        return None
    border = theme_entry.get('border', '')
    bg = theme_entry.get('background', '')
    text = theme_entry.get('text', '')
    indicator = theme_entry.get('indicator', None)
    parts = [keyword, border, bg, text]
    if original_third is not None:
        if indicator is not None:
            parts.append(indicator)
        else:
