                cm = COLORS_START_RE.match(lines[k])
                if cm:
                    # found colors {
                    colors_start = k
                    rest2 = cm.group(2)
                    d2 = 1 + rest2.count('{') - rest2.count('}')
                    kk = k
                    while d2 > 0 and kk < bar_end:
                        kk += 1
                        if kk >= n:
                            break
                        d2 += lines[kk].count('{') - lines[kk].count('}')
                    colors_end = kk
                    colors_end_line = lines[colors_end] if colors_end < n else ''
                    colors_end_indent = re.match(r'^(\s*)', colors_end_line).group(1)
                    break
                k += 1

            bar_blocks.append({
                'start': bar_start,
                'end': bar_end,
                'end_indent': end_indent,
                'colors_start': colors_start,
                'colors_end': colors_end,
                'colors_end_indent': colors_end_indent,
