    bar_by_start = {b['start']: b for b in bar_blocks}
    colors_by_start = {}
    colors_by_end = {}
    bar_by_end = {}
    for b in bar_blocks:
        if b['colors_start'] is not None:
            colors_by_start[b['colors_start']] = b
